"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["51"],{8306(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>o,contentTitle:()=>h,toc:()=>d,assets:()=>l});var s=JSON.parse('{"id":"m12-containers-k8s-gitops/lesson","title":"Kubernetes and GitOps","description":"Module 11 pointed the specialist machinery at Terraform the Dockerfile that packages a service, the Helm chart that describes how it should live in Kubernetes, and the reconciler that turns a merged Git commit into running pods. It is the same governing idea you have carried since Module 8: the agent proposes, a reconciler disposes, but now the surface is the thing your customers actually talk to. When an agent gets a Terraform change wrong, you might recreate a database. When an agent gets a deployment change wrong, every pod behind the load balancer can go unready at once, and the first anyone hears of it is the checkout page timing out.","source":"@site/docs/m12-containers-k8s-gitops/lesson.md","sourceDirName":"m12-containers-k8s-gitops","slug":"/m12-containers-k8s-gitops/lesson","permalink":"/306-agentic-devops-claude/docs/m12-containers-k8s-gitops/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Kubernetes and GitOps"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/306-agentic-devops-claude/docs/m11-iac-finops/deep-dive"},"next":{"title":"Lab: Harden and Ship an Image","permalink":"/306-agentic-devops-claude/docs/m12-containers-k8s-gitops/lab"}}'),a=n(4848),i=n(8453),r=n(7684);let o={sidebar_position:1,title:"Kubernetes and GitOps"},h="Kubernetes and GitOps",l={},d=[{value:"The container is a shipping container, and the review is the packing list",id:"the-container-is-a-shipping-container-and-the-review-is-the-packing-list",level:2},{value:"Kind is the flight simulator for your cluster",id:"kind-is-the-flight-simulator-for-your-cluster",level:2},{value:"Helm renders; you review what it rendered, not what you wrote",id:"helm-renders-you-review-what-it-rendered-not-what-you-wrote",level:2},{value:"RBAC and policy are the enforcement under the intent",id:"rbac-and-policy-are-the-enforcement-under-the-intent",level:2},{value:"The golden path: the reconciler is the only writer",id:"the-golden-path-the-reconciler-is-the-only-writer",level:2},{value:"What you will carry out of this module",id:"what-you-will-carry-out-of-this-module",level:2}];function c(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(r.A,{src:"decks/m12-containers-k8s-gitops.html",title:"M12: Kubernetes and GitOps"}),"\n",(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"kubernetes-and-gitops",children:"Kubernetes and GitOps"})}),"\n",(0,a.jsxs)(t.p,{children:["Module 11 pointed the specialist machinery at Terraform: the code that provisions the estate. This module points it one layer up, at the code that ",(0,a.jsx)(t.em,{children:"runs on"})," that estate: the Dockerfile that packages a service, the Helm chart that describes how it should live in Kubernetes, and the reconciler that turns a merged Git commit into running pods. It is the same governing idea you have carried since Module 8: the agent proposes, a reconciler disposes, but now the surface is the thing your customers actually talk to. When an agent gets a Terraform change wrong, you might recreate a database. When an agent gets a ",(0,a.jsx)(t.em,{children:"deployment"})," change wrong, every pod behind the load balancer can go unready at once, and the first anyone hears of it is the checkout page timing out."]}),"\n",(0,a.jsxs)(t.p,{children:["Here is the situation this module closes. Northstar's ",(0,a.jsx)(t.code,{children:"orders-api"})," runs fine in Docker Compose on a laptop, but production is Kubernetes, and the platform team needs the service containerized cleanly, deployed to a real cluster, and, this is the part that matters, set up so that ",(0,a.jsx)(t.em,{children:"every subsequent change"}),' to how it runs in that cluster flows through one auditable path. Not "the agent has kubectl and we trust it." A path where the agent edits desired state in Git, a human approves, and a reconciler is the single identity that writes to the cluster. You are going to build that path, put ',(0,a.jsx)(t.code,{children:"orders-api"})," on it, and then live inside it for every change after."]}),"\n",(0,a.jsx)(t.h2,{id:"the-container-is-a-shipping-container-and-the-review-is-the-packing-list",children:"The container is a shipping container, and the review is the packing list"}),"\n",(0,a.jsx)(t.p,{children:"Before Kubernetes, before Helm, before any of it, there is one artifact: the container image. Everything downstream inherits its properties, so the review starts here."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"})," a container image is a literal shipping container. The whole point of the intermodal shipping container (the steel box that revolutionized global trade) is that it is ",(0,a.jsx)(t.em,{children:"sealed, standardized, and identical"})," whether it sits on a truck, a train, or a ship. Nobody at the destination port opens it to check the packing; they trust that what was sealed at origin is what arrives. That trust is exactly what makes it fast, and exactly what makes a bad packing job dangerous. If you sealed a leaking drum of something toxic inside, it travels the whole supply chain unopened and arrives just as toxic. A container image is the same bargain: seal it once, run it identically everywhere, which means every flaw you sealed in (a secret baked into a layer, a root user, a 1.2 GB image full of build tools) ships to every environment, unopened, and runs in production exactly as you built it."]}),"\n",(0,a.jsx)(t.p,{children:"So the container review an agent runs is a packing-list review, and it has five questions, each of which maps to a property that will haunt you later if it is wrong:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Is it reproducible?"})," Does the base image pin a version (",(0,a.jsx)(t.code,{children:"python:3.12-slim"}),"), or does it float on ",(0,a.jsx)(t.code,{children:"latest"}),": so that the image you tested and the image that ships are silently different builds? A floating base is a change you did not make, applied at a time you did not choose."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Is it small?"})," A multi-stage build compiles in a fat builder stage and copies only the artifact into a slim runtime stage. The difference is not vanity: a 1.2 GB image pulls slowly on every node, holds a larger attack surface, and carries every build tool an attacker would love to find already installed."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Does it run as non-root?"})," A container that runs as root runs as root ",(0,a.jsx)(t.em,{children:"on the node"})," if it escapes its namespace. The packing-list question is: is there a ",(0,a.jsx)(t.code,{children:"USER"})," directive dropping to an unprivileged account, or does this box arrive with the keys still in it?"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Does it declare health?"})," The image and its manifest have to tell the orchestrator how to know the process is alive (liveness) and ready for traffic (readiness). Get this wrong and Kubernetes cannot tell a warming-up pod from a wedged one: which is the exact failure the Deep Dive dissects."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Are there secrets in the layers?"})," A ",(0,a.jsx)(t.code,{children:"COPY . ."})," that sweeps a ",(0,a.jsx)(t.code,{children:".env"})," file into a layer, or an ",(0,a.jsx)(t.code,{children:"ARG"})," that bakes a token into image history, ships that credential to every environment inside the sealed box. Image layers are not scratch space; they are permanent and inspectable."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["This is work an agent is genuinely good at, because it is pattern-matching against a checklist over files it can read in full: the Dockerfile, the ",(0,a.jsx)(t.code,{children:".dockerignore"}),", the compose file. The agent's advantage is that it holds all of them in context at once and never gets bored on the fifth review of the day. What it does ",(0,a.jsx)(t.em,{children:"not"})," get is the authority to push the image; that ships through CI, and the Change Gate from Module 8 denies ",(0,a.jsx)(t.code,{children:"docker push"})," from an agent identity for exactly that reason."]}),"\n",(0,a.jsx)(t.h2,{id:"kind-is-the-flight-simulator-for-your-cluster",children:"Kind is the flight simulator for your cluster"}),"\n",(0,a.jsxs)(t.p,{children:["Once the image is packed, it has to run somewhere you can break safely. That somewhere is ",(0,a.jsx)(t.strong,{children:"kind"}),", Kubernetes IN Docker, a full, real Kubernetes cluster that runs as containers on your laptop."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"})," kind is a flight simulator. It is not a toy, it runs the same API server, the same scheduler, the same kubelet as the cluster in production, the way a flight simulator runs the same avionics and flight model as the real aircraft. What it gives you is the freedom to crash. You can stall the plane, lose an engine, deploy a broken readiness probe and watch every pod go unready, and nobody is hurt, nothing costs money, and you reset and try again. The reason this matters for agentic work specifically is that an agent's proposed change needs somewhere to ",(0,a.jsx)(t.em,{children:"prove itself"})," before it touches anything real, and a laptop cluster you can create and delete in ninety seconds is that somewhere."]}),"\n",(0,a.jsx)(t.p,{children:"The catch a real team hits is memory. A full kind cluster with a control plane and a worker node, plus Argo CD, plus your services, wants headroom an 8 GB laptop does not have. Northstar ships two kind profiles for exactly this:"}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{}),(0,a.jsx)(t.th,{children:(0,a.jsx)(t.strong,{children:"Standard profile"})}),(0,a.jsx)(t.th,{children:(0,a.jsx)(t.strong,{children:"Lean profile"})})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Config file"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"kind-config.yaml"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"kind-config-lean.yaml"})})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Target RAM"}),(0,a.jsx)(t.td,{children:"16 GB or more"}),(0,a.jsx)(t.td,{children:"8 GB"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Invocation"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.code,{children:"setup.sh"})," (default)"]}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"setup.sh --lean"})})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Topology"}),(0,a.jsx)(t.td,{children:"control-plane node + worker node"}),(0,a.jsxs)(t.td,{children:["single node (control-plane ",(0,a.jsx)(t.em,{children:"and"})," worker)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Shape it teaches"}),(0,a.jsx)(t.td,{children:"production-like: workloads schedule onto the worker, control plane stays clean"}),(0,a.jsx)(t.td,{children:"everything shares one node"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Trade-off"}),(0,a.jsx)(t.td,{children:"closest to real, needs the headroom"}),(0,a.jsx)(t.td,{children:"fits a small laptop, hides node-boundary bugs"})]})]})]}),"\n",(0,a.jsxs)(t.p,{children:["The ",(0,a.jsx)(t.code,{children:"setup.sh"})," script auto-detects your RAM and warns you to pass ",(0,a.jsx)(t.code,{children:"--lean"})," below 12 GB. The lesson the agent has to internalize is that the ",(0,a.jsx)(t.em,{children:"profile changes the topology"}),", and a change validated on one profile is not automatically valid on the other. A pod that schedules fine on a single-node lean cluster might be unschedulable on a two-node standard cluster if it has a node selector; conversely a resource request that fits the standard cluster's worker might not fit when control plane and workload share one node. Adapting to the profile is part of the agent's job, not an afterthought."]}),"\n",(0,a.jsx)(t.h2,{id:"helm-renders-you-review-what-it-rendered-not-what-you-wrote",children:"Helm renders; you review what it rendered, not what you wrote"}),"\n",(0,a.jsxs)(t.p,{children:["A Helm chart is not manifests. It is a ",(0,a.jsx)(t.em,{children:"template"})," for manifests plus a ",(0,a.jsx)(t.code,{children:"values.yaml"}),' of the knobs, and the manifests only exist after Helm combines the two. This is the single most important mechanical fact in this module, and it is the direct analog of Module 11\'s "review the plan JSON, not the HCL."']}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"})," a Helm chart is a form letter with fill-in-the-blank fields, and ",(0,a.jsx)(t.code,{children:"values.yaml"}),' is the mail-merge spreadsheet. "Dear \u27E8name\u27E9, your \u27E8plan\u27E9 renews on \u27E8date\u27E9" is not the letter anyone receives: it is the template. The letter that actually lands in a mailbox exists only after the merge fills every blank. If you proofread the template you catch typos in the fixed text, but you will ',(0,a.jsx)(t.em,{children:"never"})," catch that row 400 of the spreadsheet has an empty ",(0,a.jsx)(t.code,{children:"plan"}),' field that renders "your renews on", because that defect only appears in the ',(0,a.jsx)(t.em,{children:"merged output"}),", not the template. Reviewing a Helm chart by reading its templates has the same blind spot. The defect that takes down a service (a probe pointing at a path the app does not serve, a ",(0,a.jsx)(t.code,{children:"maxUnavailable"})," set to 100%) lives in the rendered manifest, which is ",(0,a.jsx)(t.code,{children:"template"})," and ",(0,a.jsx)(t.code,{children:"values"})," combined."]}),"\n",(0,a.jsxs)(t.p,{children:["So the agent's Kubernetes review is built on one command: ",(0,a.jsx)(t.code,{children:"helm template"}),". It runs the chart through the templating engine with a given values file and emits the exact YAML that ",(0,a.jsx)(t.em,{children:"would"})," be applied: the rendered manifest, as data. From there every review is a query against that output:"]}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Does it render at all?"})," A chart with a template error fails ",(0,a.jsx)(t.code,{children:"helm template"}),", and catching that on a laptop is infinitely cheaper than catching it when Argo CD refuses to sync."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"What does the probe actually point at?"})," After rendering, the ",(0,a.jsx)(t.code,{children:"readinessProbe.httpGet.path"})," is a concrete string. The Deep Dive turns on exactly this: the template is fine, but a release candidate renders a probe pointing at ",(0,a.jsx)(t.code,{children:"/health"})," when the app serves ",(0,a.jsx)(t.code,{children:"/healthz"}),"."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"What is the rollout strategy?"})," ",(0,a.jsx)(t.code,{children:"maxUnavailable"})," and ",(0,a.jsx)(t.code,{children:"maxSurge"})," are rendered numbers. ",(0,a.jsx)(t.code,{children:'maxUnavailable: "100%"'})," means a rolling update may take every old pod down before a new one is ready: a self-inflicted outage that is invisible until the deploy runs."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Rendered-vs-running diff."})," The highest-value review compares what the chart ",(0,a.jsx)(t.em,{children:"renders"})," against what is ",(0,a.jsx)(t.em,{children:"currently running"})," in the cluster (",(0,a.jsx)(t.code,{children:"helm template"})," output diffed against ",(0,a.jsx)(t.code,{children:"kubectl get ... -o yaml"}),"). That diff is the blast radius of a sync, the exact set of changes the reconciler will make, and it is the thing a reviewer approves."]}),"\n"]}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n    V["values.yaml<br/>(the knobs)"] --\x3e HT["helm template<br/>(render)"]\n    T["chart templates<br/>(the form letter)"] --\x3e HT\n    HT --\x3e RM["rendered manifest<br/>(reviewable YAML)"]\n    RM --\x3e D["diff vs running state<br/>kubectl get -o yaml"]\n    D --\x3e AP["the sync\'s blast radius<br/>(what the reviewer approves)"]\n    style HT fill:#e8f5e9,stroke:#388e3c\n    style RM fill:#e3f2fd,stroke:#1565c0\n    style AP fill:#fff3e0,stroke:#e65100'}),"\n",(0,a.jsx)(t.p,{children:"The chart and values are the intent; the rendered manifest is the computed effect; the diff against running state is the consequence. You review the effect and the consequence, never just the intent: the same discipline as the plan JSON, one layer up the stack."}),"\n",(0,a.jsxs)(t.p,{children:["There is a subtler review the render also enables: catching what is ",(0,a.jsx)(t.em,{children:"absent"}),". A missing field is invisible when you read a template (you cannot see a block that was never written), but in the rendered manifest its absence has consequences you can name. Northstar's ",(0,a.jsx)(t.code,{children:"orders-api"})," chart, for instance, renders a pod with ",(0,a.jsxs)(t.strong,{children:["no ",(0,a.jsx)(t.code,{children:"resources"})," block"]}),': no CPU/memory requests, no limits. Read as intent, that is just a gap in a values file. Read as effect, it is a scheduling and stability decision made by omission: a pod with no requests can be scheduled onto a node with no room to actually run it, and a pod with no memory limit can grow until it starves its neighbors and gets OOM-killed under load, exactly the "resource pressure" failure the Deep Dive lists as one of its five look-alikes. The agent\'s job is to notice the absence and propose the requests and limits the workload needs, because "the chart never set them" is not the same as "the workload does not need them." Reviewing the render is as much about the fields that are missing as the ones that are wrong.']}),"\n",(0,a.jsx)(t.h2,{id:"rbac-and-policy-are-the-enforcement-under-the-intent",children:"RBAC and policy are the enforcement under the intent"}),"\n",(0,a.jsxs)(t.p,{children:["Module 8 drew a line you have used ever since: ",(0,a.jsx)(t.em,{children:"intent"})," is what a policy says should happen; ",(0,a.jsx)(t.em,{children:"enforcement"})," is what the system physically prevents regardless of intent. In Kubernetes, that line has names, and the agent needs to read them the way it reads Helm values: as facts about what is and is not possible, not aspirations."]}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Service accounts and RBAC."})," Every pod runs ",(0,a.jsx)(t.em,{children:"as"})," a service account, and that account's ",(0,a.jsx)(t.code,{children:"Role"}),"/",(0,a.jsx)(t.code,{children:"ClusterRole"})," bindings define what it can touch through the API. Northstar's read-only kubeconfig (",(0,a.jsx)(t.code,{children:"platform/kubeconfigs/readonly.yaml"}),") binds a ",(0,a.jsx)(t.code,{children:"ClusterRole"})," whose verbs are exactly ",(0,a.jsx)(t.code,{children:"get"}),", ",(0,a.jsx)(t.code,{children:"list"}),", ",(0,a.jsx)(t.code,{children:"watch"}),": no ",(0,a.jsx)(t.code,{children:"create"}),", ",(0,a.jsx)(t.code,{children:"update"}),", ",(0,a.jsx)(t.code,{children:"delete"}),". That is not a promise the agent will only read; it is an identity that ",(0,a.jsx)(t.em,{children:"cannot"}),' write, checked by the API server on every call. The agent-facing lesson: read the RBAC to know what an identity can actually do, and never assume a "read-only" label without confirming the verbs.']}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Network policy."})," By default, every pod in a namespace can talk to every other pod: a flat network. A ",(0,a.jsx)(t.code,{children:"NetworkPolicy"})," narrows that. Northstar ships an intentionally permissive ",(0,a.jsx)(t.code,{children:"allow-all-ingress"})," policy today (hardened later in the SecOps module), and the honest thing is to ",(0,a.jsx)(t.em,{children:"read the policy and report what it actually allows"}),", not what its name suggests."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Admission checks (Pod Security)."})," The ",(0,a.jsx)(t.code,{children:"northstar"})," namespace carries Pod Security Standard labels, ",(0,a.jsx)(t.code,{children:"enforce: baseline"}),", ",(0,a.jsx)(t.code,{children:"warn: restricted"}),", ",(0,a.jsx)(t.code,{children:"audit: restricted"}),". Those are admission-time gates: a pod that violates the ",(0,a.jsx)(t.code,{children:"baseline"})," standard is ",(0,a.jsx)(t.em,{children:"rejected at creation"})," by the API server, before it ever schedules. This is enforcement in its purest form, the cluster refuses the object, no matter who submitted it."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:["The reason all three matter to an agent is the same reason the Change Gate matters: an agent operating in a cluster should be ",(0,a.jsx)(t.em,{children:"bounded by the cluster's own controls"}),", so that even a confused or misdirected agent cannot exceed them. The read-only kubeconfig is the agent's default identity for a reason: it lets the agent investigate freely and prevents it from writing at all."]}),"\n",(0,a.jsx)(t.h2,{id:"the-golden-path-the-reconciler-is-the-only-writer",children:"The golden path: the reconciler is the only writer"}),"\n",(0,a.jsxs)(t.p,{children:["Everything above converges on one model, and it is the whole point of the module. The agent has ",(0,a.jsx)(t.strong,{children:"no direct cluster-write path"}),". It edits desired state in Git; a human reviews and merges; Argo CD, the reconciler, is the single identity that turns merged Git state into cluster state."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Analogy:"})," think of the cluster as a bank vault with exactly one key, and that key is held by an automated system, not a person and not an agent. You do not walk up to the vault and move money. You submit a signed transfer request, an officer approves it, and the automated system (the only holder of the key) executes it and logs every move. The agent is the customer filling out the transfer slip. It can propose any change it likes, in perfect detail, and it physically cannot open the vault. Argo CD is the automated system with the key: it watches the merged Git branch and reconciles the cluster to match, continuously, and it is the ",(0,a.jsx)(t.em,{children:"only"})," identity with write access. If the live cluster drifts from Git (someone hand-edits a deployment), the reconciler pulls it back. Git is the source of truth; the cluster is a projection of it."]}),"\n",(0,a.jsx)(t.p,{children:"This is why the golden path has five stops, and why the agent's authority ends at the second:"}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n    C["1. candidate<br/>(agent edits Helm<br/>values on a branch)"] --\x3e A["2. approval<br/>(human reviews<br/>the rendered diff)"]\n    A --\x3e M["3. merge<br/>(approved change<br/>lands on main)"]\n    M --\x3e S["4. sync<br/>(Argo CD reconciles<br/>cluster to Git)"]\n    S --\x3e Ver["5. verify<br/>(rollout healthy,<br/>pods ready)"]\n    style C fill:#e3f2fd,stroke:#1565c0\n    style S fill:#f3e5f5,stroke:#6a1b9a\n    style Ver fill:#e8f5e9,stroke:#388e3c'}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Candidate."})," The ",(0,a.jsx)(t.code,{children:"platform-engineer"})," agent edits ",(0,a.jsx)(t.code,{children:"values.yaml"})," (or a manifest) on a branch and validates it renders with ",(0,a.jsx)(t.code,{children:"helm template"})," and ",(0,a.jsx)(t.code,{children:"helm lint"}),". It runs ",(0,a.jsx)(t.code,{children:"scripts/gitops-propose.sh"}),", which stages the desired-state change, shows the diff, and ",(0,a.jsx)(t.em,{children:"stops"}),": printing the human's next steps. That script refuses to touch a cluster; it is the agent's structural stopping point."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Approval."})," A human (or the read-only ",(0,a.jsx)(t.code,{children:"change-reviewer"})," agent) reviews the rendered diff, the blast radius of the sync, against the change contract."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Merge."})," The approved change lands on ",(0,a.jsx)(t.code,{children:"main"})," in the Git remote Argo CD watches."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Sync."})," Argo CD detects the new commit and reconciles the cluster to match. This is the ",(0,a.jsx)(t.em,{children:"only"})," write to the cluster, and it comes from the reconciler's identity, never the agent's."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Verify."})," The rollout completes, pods pass readiness, and the change is confirmed live: or the rollout stalls and you have an incident, which is the Deep Dive."]}),"\n"]}),"\n",(0,a.jsxs)(t.p,{children:['The reason this shape is worth the ceremony is that it makes "the agent did something to production" ',(0,a.jsx)(t.em,{children:"impossible to do by accident"}),". There is no ",(0,a.jsx)(t.code,{children:"kubectl apply"})," for the agent to fat-finger, no ",(0,a.jsx)(t.code,{children:"helm upgrade"}),' for a runaway loop to execute against the wrong context. The agent\'s most dangerous possible action is proposing a bad change in Git: which a human reads before it ever syncs. The blast radius of an agent mistake is bounded to "a pull request someone rejects."']}),"\n",(0,a.jsx)(t.admonition,{title:"Where this connects",type:"info",children:(0,a.jsxs)(t.p,{children:["The pieces you assemble here were built in earlier modules: Module 1 fixed the ",(0,a.jsx)(t.code,{children:"/health"})," vs ",(0,a.jsx)(t.code,{children:"/healthz"})," readiness bug in the app and the chart (the Deep Dive watches a stale release candidate reintroduce it); Module 8 built the candidate \u2192 approval \u2192 merge \u2192 sync change path and the Environment Contract; Module 9 built the ",(0,a.jsx)(t.code,{children:"platform-engineer"})," role you use for Kubernetes work; Module 11 used git worktree isolation for infrastructure changes, and the same pattern applies to desired-state changes here."]})}),"\n",(0,a.jsx)(t.h2,{id:"what-you-will-carry-out-of-this-module",children:"What you will carry out of this module"}),"\n",(0,a.jsxs)(t.p,{children:["You will have containerized ",(0,a.jsx)(t.code,{children:"orders-api"})," and reviewed the Dockerfile against the five packing-list questions; stood up a real Kubernetes cluster on kind and adapted to its memory profile; rendered a Helm chart and reviewed the ",(0,a.jsx)(t.em,{children:"output"}),", not the template; read the RBAC, network policy, and admission labels that bound what any identity, including the agent, can do; and put ",(0,a.jsx)(t.code,{children:"orders-api"})," on the golden path, where every change from here flows candidate \u2192 approval \u2192 merge \u2192 sync \u2192 verify with the reconciler as the only writer."]}),"\n",(0,a.jsxs)(t.p,{children:["The Deep Dive then breaks it on purpose. A misconfigured readiness probe produces a rollout that fails with ",(0,a.jsx)(t.em,{children:"misleading"}),' symptoms, the application is healthy, but the pods are not ready, and the difference between "the app is down" and "the probe is wrong" is the difference between a thirty-minute incident and a three-hour one. You will learn to separate application health from probe configuration from rollout state from routing from resource pressure, five things that all look like "the service is broken" and each of which is fixed a completely different way. And you will fix it the only way this module allows: through Git, through the reconciler, on the golden path.']})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},7684(e,t,n){n.d(t,{A:()=>i});var s=n(4848);n(6540);var a=n(6497);function i({src:e,title:t="Slides"}){let n=(0,a.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,s.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var s=n(6540);let a={},i=s.createContext(a);function r(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);